[Write file: /Users/ben/Desktop/zzz-AI-Transcript-Data/site-agent/site/styles.css]
/* =====================================================================
   LT 2010 — Computer Skills for the Information Age
   "The Book & The Machine" — humanist book serif meets a monospaced
   machine voice, warm paper, one electric cobalt accent.
   ===================================================================== */

/* ---- Reset ---------------------------------------------------------- */
*, *::before, *::after { box-sizing: border-box; }
* { margin: 0; }
html { -webkit-text-size-adjust: 100%; }
body { min-height: 100vh; text-rendering: optimizeLegibility;
       -webkit-font-smoothing: antialiased; }
img, svg { display: block; max-width: 100%; }
a { color: inherit; }
ul { list-style: none; padding: 0; }
button { font: inherit; color: inherit; background: none; border: none; cursor: pointer; }

/* ---- Tokens --------------------------------------------------------- */
:root {
  --font-display: "Iowan Old Style", "Palatino Linotype", Palatino,
                  "Book Antiqua", Georgia, "Times New Roman", serif;
  --font-sans: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --font-mono: ui-monospace, "SF Mono", "Cascadia Code", Menlo, Consolas, monospace;

  --paper:   #f2f1ec;   /* warm greige ground             */
  --raised:  #fbfaf6;   /* lifted cards                   */
  --ink:     #16181d;   /* headings / near-black          */
  --body:    #3b3f47;   /* running text                   */
  --muted:   #6e7078;   /* captions, meta                 */
  --line:    #dcdad2;   /* hairlines                      */
  --line-2:  #cbc8be;   /* stronger rules                 */
  --accent:  #1f3bd0;   /* electric cobalt — the "signal" */
  --accent-2:#16299a;   /* darker cobalt for small text   */
  --accent-wash: rgba(31,59,208,.07);
  --flag:    #a4660f;   /* ochre — deadline / 2-week flag  */
  --flag-wash: rgba(164,102,15,.10);

  --maxw: 1120px;
  --measure: 64ch;
  --radius: 4px;
  --ease: cubic-bezier(.2,.7,.2,1);
}

@media (prefers-color-scheme: dark) {
  :root {
    --paper:   #10131a;
    --raised:  #171b24;
    --ink:     #eceae2;
    --body:    #c4c3bb;
    --muted:   #8a8c93;
    --line:    #262b35;
    --line-2:  #333a47;
    --accent:  #6e86ff;
    --accent-2:#93a4ff;
    --accent-wash: rgba(110,134,255,.10);
    --flag:    #e0a73a;
    --flag-wash: rgba(224,167,58,.13);
  }
}
/* Viewer toggle wins in both directions */
:root[data-theme="light"] {
  --paper:#f2f1ec; --raised:#fbfaf6; --ink:#16181d; --body:#3b3f47; --muted:#6e7078;
  --line:#dcdad2; --line-2:#cbc8be; --accent:#1f3bd0; --accent-2:#16299a;
  --accent-wash:rgba(31,59,208,.07); --flag:#a4660f; --flag-wash:rgba(164,102,15,.10);
}
:root[data-theme="dark"] {
  --paper:#10131a; --raised:#171b24; --ink:#eceae2; --body:#c4c3bb; --muted:#8a8c93;
  --line:#262b35; --line-2:#333a47; --accent:#6e86ff; --accent-2:#93a4ff;
  --accent-wash:rgba(110,134,255,.10); --flag:#e0a73a; --flag-wash:rgba(224,167,58,.13);
}

/* ---- Base ----------------------------------------------------------- */
body {
  font-family: var(--font-sans);
  font-size: 1.0625rem;
  line-height: 1.65;
  color: var(--body);
  background: var(--paper);
  background-image:
    radial-gradient(var(--line) .6px, transparent .6px);
  background-size: 26px 26px;
  background-attachment: fixed;
}

.wrap { width: 100%; max-width: var(--maxw); margin-inline: auto; padding-inline: clamp(1.25rem, 5vw, 3rem); }

section { position: relative; }
.band { padding-block: clamp(3.5rem, 8vw, 6.5rem); scroll-margin-top: 5rem; }
.band + .band { border-top: 1px solid var(--line); }

/* ---- Type utilities ------------------------------------------------- */
h1, h2, h3 { font-family: var(--font-display); color: var(--ink);
             font-weight: 600; line-height: 1.08; text-wrap: balance;
             letter-spacing: -.01em; }
p { max-width: var(--measure); }

.eyebrow {
  font-family: var(--font-mono);
  font-size: .74rem; font-weight: 600;
  text-transform: uppercase; letter-spacing: .18em;
  color: var(--accent-2);
  display: inline-flex; align-items: center; gap: .6em;
}
.eyebrow::before {
  content: ""; width: 1.6rem; height: 1px; background: var(--accent);
  display: inline-block;
}
.mono { font-family: var(--font-mono); font-variant-numeric: tabular-nums; }
.lead { font-size: clamp(1.1rem, 1.6vw, 1.3rem); color: var(--ink); line-height: 1.5; }

.section-head { display: flex; flex-direction: column; gap: .9rem; margin-bottom: clamp(2rem,4vw,3rem); }
.section-head h2 { font-size: clamp(1.9rem, 4vw, 2.8rem); }
.section-head p { color: var(--body); }

a.link {
  color: var(--accent-2); text-decoration: none;
  background-image: linear-gradient(var(--accent), var(--accent));
  background-size: 100% 1px; background-position: 0 100%; background-repeat: no-repeat;
  padding-bottom: 1px; transition: background-size .25s var(--ease);
}
a.link:hover { background-size: 100% 2px; }

:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: 2px; }

/* ---- Top bar -------------------------------------------------------- */
.topbar {
  position: sticky; top: 0; z-index: 50;
  background: color-mix(in srgb, var(--paper) 86%, transparent);
  -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--line);
}
.topbar .wrap { display: flex; align-items: center; gap: 1.5rem;
                min-height: 3.6rem; padding-block: .5rem; }
.brand { display: flex; align-items: baseline; gap: .7rem; text-decoration: none; }
.brand .code { font-family: var(--font-mono); font-weight: 700; font-size: .9rem;
               letter-spacing: .06em; color: var(--ink);
               border: 1px solid var(--line-2); padding: .18em .5em; border-radius: 3px; }
.brand .name { font-family: var(--font-display); font-size: 1rem; color: var(--ink);
               font-weight: 600; }
.nav { margin-left: auto; display: flex; align-items: center; gap: 1.4rem; }
.nav a { font-size: .86rem; text-decoration: none; color: var(--muted);
         transition: color .2s var(--ease); }
.nav a:hover { color: var(--ink); }
.toggle { display: inline-grid; place-items: center; width: 2.1rem; height: 2.1rem;
          border: 1px solid var(--line-2); border-radius: 50%; color: var(--ink);
          transition: border-color .2s var(--ease), transform .3s var(--ease); }
.toggle:hover { border-color: var(--accent); transform: rotate(-15deg); }
.toggle svg { width: 1.05rem; height: 1.05rem; }
.toggle .moon { display: none; }
:root[data-theme="dark"] .toggle .sun { display: none; }
:root[data-theme="dark"] .toggle .moon { display: block; }
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) .toggle .sun { display: none; }
  :root:not([data-theme="light"]) .toggle .moon { display: block; }
}
@media (max-width: 720px) { .nav a { display: none; } }

/* ---- Hero ----------------------------------------------------------- */
.hero { padding-block: clamp(3.5rem, 9vw, 7rem) clamp(3rem, 6vw, 5rem);
        position: relative; overflow: hidden; }
.hero .wrap { position: relative; z-index: 1; }
.hero .eyebrow { margin-bottom: 1.6rem; }
.hero h1 { font-size: clamp(2.7rem, 7vw, 5rem); color: var(--ink);
           max-width: 15ch; margin-bottom: 1.4rem; }
.hero h1 em { font-style: italic; color: var(--accent-2); }
.hero .lead { max-width: 46ch; margin-bottom: 2.4rem; }

.meta-row { display: flex; flex-wrap: wrap; gap: .6rem .7rem; }
.chip { font-family: var(--font-mono); font-size: .76rem; letter-spacing: .04em;
        color: var(--ink); background: var(--raised);
        border: 1px solid var(--line-2); border-radius: 100px;
        padding: .4em .9em; display: inline-flex; align-items: center; gap: .5em; }
.chip .dot { width: .42em; height: .42em; border-radius: 50%; background: var(--accent); }

/* faint plotted-data motif in the hero */
.hero::after {
  content: ""; position: absolute; inset: 0; z-index: 0; pointer-events: none;
  background:
    linear-gradient(to right, var(--accent-wash), transparent 40%);
  -webkit-mask-image: linear-gradient(to bottom, #000, transparent 85%);
          mask-image: linear-gradient(to bottom, #000, transparent 85%);
}

/* ---- Goals ---------------------------------------------------------- */
.goals-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
              gap: 1px; background: var(--line); border: 1px solid var(--line);
              border-radius: var(--radius); overflow: hidden; }
.goal { background: var(--paper); padding: 1.6rem 1.5rem 1.8rem;
        display: flex; flex-direction: column; gap: .55rem;
        transition: background .25s var(--ease); }
.goal:hover { background: var(--raised); }
.goal .g-no { font-family: var(--font-mono); font-size: .78rem; color: var(--accent-2);
              letter-spacing: .08em; }
.goal h3 { font-size: 1.24rem; color: var(--ink); }
.goal p { font-size: .95rem; color: var(--body); margin: 0; }

/* ---- Schedule / timeline -------------------------------------------- */
.legend { display: flex; flex-wrap: wrap; gap: 1rem 1.4rem; margin-bottom: 2rem;
          font-size: .82rem; color: var(--muted); }
.legend span { display: inline-flex; align-items: center; gap: .5em; }
.key { width: .85rem; height: .85rem; border-radius: 3px; flex: none; }
.key.disc { background: var(--accent-wash); border: 1px solid var(--accent); }
.key.assign { background: var(--accent); }
.key.flag { background: var(--flag-wash); border: 1px solid var(--flag); }

.schedule { position: relative; }
.schedule::before {           /* the spine */
  content: ""; position: absolute; left: calc(3.2rem - .5px); top: .4rem; bottom: .4rem;
  width: 1px; background: var(--line-2);
}
.wk { position: relative; display: grid;
      grid-template-columns: 3.2rem 1fr auto; gap: 0 1.6rem;
      padding: 1.35rem 0; align-items: start;
      border-top: 1px solid var(--line); }
.wk:first-child { border-top: none; }
.wk-no { position: relative; font-family: var(--font-mono); font-size: 1.05rem;
         font-weight: 600; color: var(--ink); letter-spacing: -.02em;
         padding-left: 0; z-index: 1; }
.wk-no::before {              /* node on the spine */
  content: ""; position: absolute; left: calc(3.2rem - 1.6rem - 4.5px);
  top: .55em; width: 9px; height: 9px; border-radius: 50%;
  background: var(--paper); border: 2px solid var(--line-2);
  transition: border-color .25s var(--ease), background .25s var(--ease);
}
.wk:hover .wk-no::before { border-color: var(--accent); background: var(--accent); }
.wk-no small { display: block; font-size: .62rem; letter-spacing: .16em;
               text-transform: uppercase; color: var(--muted); font-weight: 400; }
.wk-body h3 { font-size: 1.28rem; color: var(--ink); margin-bottom: .55rem; }
.tags { display: flex; flex-wrap: wrap; gap: .45rem; }
.tag { font-size: .78rem; padding: .28em .7em; border-radius: 100px;
       background: var(--accent-wash); color: var(--accent-2);
       border: 1px solid color-mix(in srgb, var(--accent) 30%, transparent); }
.tag.assign { background: var(--accent); color: #fff; border-color: var(--accent);
              font-weight: 600; }
:root[data-theme="dark"] .tag.assign { color: #10131a; }
@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) .tag.assign { color:#10131a; } }
.tag.flag { background: var(--flag-wash); color: var(--flag);
            border-color: color-mix(in srgb, var(--flag) 40%, transparent); }
.wk-due { text-align: right; font-family: var(--font-mono);
          font-variant-numeric: tabular-nums; white-space: nowrap; }
.wk-due .d-label { display: block; font-size: .6rem; letter-spacing: .16em;
                   text-transform: uppercase; color: var(--muted); }
.wk-due time { font-size: 1rem; color: var(--ink); font-weight: 600; }

/* break divider */
.break { display: flex; align-items: center; gap: 1rem; padding: 1.1rem 0;
         border-top: 1px solid var(--line); color: var(--muted);
         font-family: var(--font-mono); font-size: .78rem; letter-spacing: .12em;
         text-transform: uppercase; }
.break::after { content: ""; flex: 1; height: 1px;
                background: repeating-linear-gradient(90deg, var(--line-2) 0 6px, transparent 6px 12px); }

@media (max-width: 640px) {
  .schedule::before { left: calc(2.4rem - .5px); }
  .wk { grid-template-columns: 2.4rem 1fr; gap: 0 1rem; }
  .wk-no::before { left: calc(2.4rem - 1rem - 4.5px); }
  .wk-due { grid-column: 2; text-align: left; margin-top: .7rem; }
  .wk-due .d-label { display: inline; margin-right: .5em; }
}

/* ---- Assignments ---------------------------------------------------- */
.assign-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px,1fr));
               gap: 1.1rem; }
.acard { background: var(--raised); border: 1px solid var(--line);
         border-radius: var(--radius); padding: 1.6rem 1.5rem;
         display: flex; flex-direction: column; gap: .6rem;
         position: relative; overflow: hidden;
         transition: border-color .25s var(--ease), transform .25s var(--ease); }
.acard:hover { border-color: var(--accent); transform: translateY(-3px); }
.acard .a-tag { font-family: var(--font-mono); font-size: .72rem; letter-spacing: .1em;
                text-transform: uppercase; color: var(--accent-2); }
.acard h3 { font-size: 1.2rem; color: var(--ink); }
.acard p { font-size: .93rem; margin: 0; color: var(--body); }
.acard .due { margin-top: auto; font-family: var(--font-mono);
              font-size: .82rem; color: var(--muted); padding-top: .5rem; }
.acard .due b { color: var(--ink); font-weight: 600; }
.acard.final { background: var(--accent); border-color: var(--accent); }
.acard.final .a-tag, .acard.final h3, .acard.final p,
.acard.final .due, .acard.final .due b { color: #fff; }
:root[data-theme="dark"] .acard.final,
:root[data-theme="dark"] .acard.final * { color: #10131a; }
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) .acard.final,
  :root:not([data-theme="light"]) .acard.final * { color:#10131a; }
}

/* ---- FAQ ------------------------------------------------------------ */
.faq { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px,1fr)); gap: 1.5rem 2.4rem; }
.qa { border-top: 2px solid var(--ink); padding-top: 1rem; }
.qa h3 { font-size: 1.12rem; color: var(--ink); margin-bottom: .45rem; }
.qa p { font-size: .95rem; margin: 0; }

/* ---- Footer --------------------------------------------------------- */
.foot { border-top: 1px solid var(--line-2); padding-block: 2.6rem; }
.foot .wrap { display: flex; flex-wrap: wrap; gap: 1rem 2rem; align-items: baseline;
              justify-content: space-between; }
.foot .code { font-family: var(--font-mono); font-weight: 700; color: var(--ink);
              letter-spacing: .05em; }
.foot p { font-size: .82rem; color: var(--muted); margin: 0; max-width: 48ch; }

/* ---- Reveal animation ---------------------------------------------- */
.reveal { opacity: 0; transform: translateY(18px); transition: opacity .7s var(--ease), transform .7s var(--ease); }
.reveal.in { opacity: 1; transform: none; }

@media (prefers-reduced-motion: reduce) {
  * { scroll-behavior: auto !important; }
  .reveal { opacity: 1; transform: none; transition: none; }
  .toggle:hover, .acard:hover { transform: none; }
}
html { scroll-behavior: smooth; }

