/* LT 2010 — theme toggle, mobile nav, scroll reveals.
   The `js` class and saved theme are set by an inline script in <head>
   before first paint (prevents theme flash; keeps content visible if JS is off). */
(function () {
  "use strict";

  var root = document.documentElement;
  root.classList.add("js"); // safety: ensure set even if head script was stripped

  /* ---- Theme toggle -------------------------------------------------- */
  var KEY = "lt2010-theme";
  var toggle = document.getElementById("themeToggle");

  function currentTheme() {
    var c = root.getAttribute("data-theme");
    if (c === "light" || c === "dark") return c;
    return window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
  }
  function syncPressed() {
    if (toggle) toggle.setAttribute("aria-pressed", currentTheme() === "dark" ? "true" : "false");
  }
  syncPressed();

  if (toggle) {
    toggle.addEventListener("click", function () {
      var next = currentTheme() === "dark" ? "light" : "dark";
      root.setAttribute("data-theme", next);
      try { localStorage.setItem(KEY, next); } catch (e) {}
      syncPressed();
    });
  }

  /* ---- Mobile navigation (disclosure) -------------------------------- */
  var navToggle = document.getElementById("navToggle");
  var nav = document.getElementById("siteNav");

  function closeNav() {
    if (nav) nav.classList.remove("open");
    if (navToggle) navToggle.setAttribute("aria-expanded", "false");
  }
  if (navToggle && nav) {
    navToggle.addEventListener("click", function (e) {
      e.stopPropagation();
      var open = nav.classList.toggle("open");
      navToggle.setAttribute("aria-expanded", open ? "true" : "false");
    });
    nav.addEventListener("click", function (e) {
      if (e.target.closest("a")) closeNav();
    });
    document.addEventListener("click", function (e) {
      if (nav.classList.contains("open") && !nav.contains(e.target) && e.target !== navToggle) closeNav();
    });
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape") closeNav();
    });
    window.addEventListener("resize", function () {
      if (window.innerWidth > 760) closeNav();
    });
  }

  /* ---- Scroll reveal ------------------------------------------------- */
  var reveals = document.querySelectorAll(".reveal");
  var reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  if (reduce || !("IntersectionObserver" in window)) {
    reveals.forEach(function (el) { el.classList.add("in"); });
    return;
  }

  var io = new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      if (entry.isIntersecting) {
        entry.target.classList.add("in");
        io.unobserve(entry.target);
      }
    });
  }, { rootMargin: "0px 0px -8% 0px", threshold: 0.08 });

  reveals.forEach(function (el, i) {
    el.style.transitionDelay = Math.min(i % 6, 5) * 45 + "ms";
    io.observe(el);
  });
})();

