58	    });
59	  }
60	
61	  /* ---- Scroll reveal ------------------------------------------------- */
62	  var reveals = document.querySelectorAll(".reveal");
63	  var reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
64	
65	  if (reduce || !("IntersectionObserver" in window)) {
66	    reveals.forEach(function (el) { el.classList.add("in"); });
67	    return;
68	  }
69	
70	  var io = new IntersectionObserver(function (entries) {
71	    entries.forEach(function (entry) {
72	      if (entry.isIntersecting) {
73	        entry.target.classList.add("in");
74	        io.unobserve(entry.target);
75	      }
76	    });
77	  }, { rootMargin: "0px 0px -8% 0px", threshold: 0.08 });
78	
79	  reveals.forEach(function (el, i) {
80	    el.style.transitionDelay = Math.min(i % 6, 5) * 45 + "ms";
81	    io.observe(el);
82	  });
83	})();
