30	  --ink:     #171a21;   /* headings — ink with a faint blue bias */
31	  --body:    #3a3e46;   /* running text                   */
32	  --muted:   #585b63;   /* captions, meta (AA on paper)   */
33	  --line:    #d6d8dc;   /* hairlines                      */
34	  --line-2:  #c3c6cc;   /* stronger rules                 */
35	  --accent:  #1f3bd0;   /* electric cobalt — the one accent */
