377	  gap: 1rem; }
378	details.disc > summary::-webkit-details-marker { display: none; }
379	details.disc > summary::after { content: "+"; font-family: var(--font-mono);
380	  color: var(--accent-2); font-size: 1.35rem; line-height: 1; font-weight: 400; }
381	details.disc[open] > summary::after { content: "\2212"; }
382	details.disc .body { padding: 0 1.25rem 1.25rem; }
383	details.disc .body p { margin: 0 0 .7rem; color: var(--body); }
384	details.disc .body p:last-child { margin-bottom: 0; }
385	details.disc .body ul { list-style: disc; padding-left: 1.2rem; margin-bottom: .7rem;
386	  display: flex; flex-direction: column; gap: .4rem; }
387	details.disc .body li { color: var(--body); }
388	details.disc .body strong { color: var(--ink); }
389	
390	/* ---- Assignments ---------------------------------------------------- */
391	.assign-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px,1fr));
392	               gap: 1.1rem; }
393	.acard { background: var(--raised); border: 1px solid var(--line);
394	         border-radius: var(--radius); padding: 1.6rem 1.5rem;
395	         display: flex; flex-direction: column; gap: .6rem;
396	         position: relative; overflow: hidden;
397	         transition: border-color .25s var(--ease), transform .25s var(--ease); }
398	.acard:hover { border-color: var(--accent); transform: translateY(-3px); }
399	.acard .a-tag { font-family: var(--font-mono); font-size: .72rem; letter-spacing: .1em;
400	                text-transform: uppercase; color: var(--accent-2); }
401	.acard h3 { font-size: 1.2rem; color: var(--ink); }
402	.acard p { font-size: .93rem; margin: 0; color: var(--body); }
403	.acard .due { margin-top: auto; font-family: var(--font-mono);
404	              font-size: .82rem; color: var(--muted); padding-top: .5rem; }
405	.acard .due b { color: var(--ink); font-weight: 600; }
406	.acard.final { background: var(--accent); border-color: var(--accent); }
407	.acard.final .a-tag, .acard.final h3, .acard.final p,
408	.acard.final .due, .acard.final .due b { color: #fff; }
409	:root[data-theme="dark"] .acard.final,
410	:root[data-theme="dark"] .acard.final * { color: #10131a; }
411	@media (prefers-color-scheme: dark) {
412	  :root:not([data-theme="light"]) .acard.final,
413	  :root:not([data-theme="light"]) .acard.final * { color:#10131a; }
414	}
415	
416	/* ---- Footer --------------------------------------------------------- */
417	.foot { border-top: 1px solid var(--line-2); padding-block: 2.6rem; }
418	.foot .wrap { display: grid; gap: 1rem 2rem;
419	              grid-template-columns: 1fr auto; align-items: start; }
420	.foot-id { display: flex; flex-direction: column; gap: .25rem; }
421	.foot .code { font-family: var(--font-mono); font-weight: 700; color: var(--ink);
422	              letter-spacing: .05em; }
423	.foot-org { font-size: .84rem; }
424	.foot-links { display: flex; flex-wrap: wrap; gap: .4rem 1.2rem; font-size: .86rem;
425	              justify-content: flex-end; }
426	.foot-note { grid-column: 1 / -1; font-size: .8rem; color: var(--muted);
427	             margin: 0; max-width: 60ch; }
428	@media (max-width: 640px) {
429	  .foot .wrap { grid-template-columns: 1fr; }
430	  .foot-links { justify-content: flex-start; }
431	}
432	
433	/* ---- Reveal animation (JS-gated so content shows if JS is off) ------- */
434	html.js .reveal { opacity: 0; transform: translateY(18px);
435	                  transition: opacity .7s var(--ease), transform .7s var(--ease); }
436	html.js .reveal.in { opacity: 1; transform: none; }
437	
438	@media (prefers-reduced-motion: reduce) {
439	  * { scroll-behavior: auto !important; }
440	  html.js .reveal { opacity: 1; transform: none; transition: none; }
441	  .toggle:hover, .nav-toggle:hover, .acard:hover, .btn:hover { transform: none; }
442	}
443	html { scroll-behavior: smooth; }
